* Create lag rdq and double lagged rdq, create an indicator for missing rdq, replace missing rdq;
* Missing rdq ends up not being used;

proc sort data=fundq nodupkey;
	by gvkey datadate;
run;

data fundq; set fundq;
	missingrdq= missing(rdq);
	if missing(rdq) then rdq = datadate+45;
	earlyrdq= rdq <= datadate;
	if rdq <= datadate then rdq = datadate+45;
	laterdq =rdq >= intnx("quarter", datadate, +2, "sameday");
	if rdq >= intnx("quarter", datadate, +2, "sameday") then rdq = intnx("quarter", datadate, +2, "sameday");
	format rdq Date9.;
run;

proc sql;
	create table final as
	select a.*, b.rdq, b.rdqlag1, b.lead_rdq, b.datadate, b.missingrdq, b.laterdq, b.earlyrdq from emp_final a inner join fundq b
	on a.gvkey = b.gvkey and a.reviewdatetime >= b.rdqlag1+4 and a.reviewdatetime <= b.lead_rdq+3;
